#include "ux_support.h"
#include "book_covers.h"
#include "import_inspector.h"
#include <QImage>
#include <QCoreApplication>
#include <QBuffer>
#include <QTemporaryDir>
int main(int argc,char**argv){QCoreApplication app(argc,argv);try{CHECK(argc==5);const auto source=std::filesystem::path(argv[1]),data=std::filesystem::path(argv[2]),bin=std::filesystem::path(argv[3]),sys=std::filesystem::path(argv[4]);const auto application=stage(source,data,bin,sys);const auto before=underlay::digest(underlay::readBounded(source/"fixtures/cover-test.epub",1024*1024));const auto root=data/"library";underlay::privateDirectory(root);library::Document epub,pdf;{library::Store store(root);epub=store.importDocument(source/"fixtures/cover-test.epub","Cover test",library::inspectDocument);pdf=store.importDocument(source/"fixtures/inkbound-device-test.pdf","Front page",library::inspectDocument);}std::filesystem::remove(library::documentRoot(root,epub.id)/"cover.png");covers::Service service;
 for(const auto& d:{epub,pdf}){CHECK(service.request({application,library::documentRoot(root,d.id),d.id,d.sha256}));until([&]{service.collect();return service.drained();});const auto image=service.find(d.id,d.sha256);CHECK(image&&image->width<=covers::Width&&image->height<=covers::Height&&image->pixels.size()==std::size_t(image->width)*image->height);if(d.id==epub.id)CHECK((image->pixels[std::size_t(image->height/2)*image->width+image->width/2]&0xffffffu)==0x204050u);else CHECK(std::any_of(image->pixels.begin(),image->pixels.end(),[](auto p){return (p&0xffffffu)<0x808080u;}));CHECK(!service.find(d.id,QString(64,'0')));}CHECK(service.failures()==0&&service.cached()==2&&!std::filesystem::exists(library::documentRoot(root,epub.id)/"cover.png"));CHECK(underlay::digest(underlay::readBounded(source/"fixtures/cover-test.epub",1024*1024))==before);
 const auto fake=data/"fake";underlay::privateDirectory(fake/"bin");const QString hash(64,'f');QImage noise(covers::Width,covers::Height,QImage::Format_RGB32);std::uint32_t random=17;for(int y=0;y<noise.height();++y){auto line=reinterpret_cast<std::uint32_t*>(noise.scanLine(y));for(int x=0;x<noise.width();++x){random=random*1664525u+1013904223u;line[x]=0xff000000u|(random&0xffffffu);}}QByteArray png;QBuffer encoded(&png);CHECK(encoded.open(QIODevice::WriteOnly)&&noise.save(&encoded,"PNG")&&png.size()>65536&&png.size()<1024*1024);const auto payload=QJsonDocument(QJsonObject{{"version",1},{"source",hash},{"png",QString::fromLatin1(png.toBase64())}}).toJson(QJsonDocument::Compact);std::printf("COVER_BURST png_bytes=%lld wire_bytes=%lld png_sha256=%s\n",static_cast<long long>(png.size()),static_cast<long long>(payload.size()),underlay::digest(png).toHex().constData());std::fflush(stdout);underlay::atomicFile(fake/"bin/reader-experience1-prepare",QByteArray("#!/bin/sh\nprintf '%s' '")+payload+"'\n");CHECK(chmod((fake/"bin/reader-experience1-prepare").c_str(),0700)==0);
 covers::Service bounded;for(int n=0;n<15;++n){const auto id=QString("22222222-2222-4222-8222-%1").arg(n,12,10,QChar('0'));CHECK(bounded.request({fake,data/id.toStdString(),id,hash}));until([&]{bounded.collect();return bounded.drained();});CHECK(bounded.find(id,hash)&&bounded.cached()<=covers::CacheLimit);}CHECK(bounded.cached()==covers::CacheLimit&&bounded.failures()==0);
 const auto slow=data/"slow";underlay::privateDirectory(slow/"bin");underlay::atomicFile(slow/"bin/reader-experience1-prepare","#!/bin/sh\nexec sleep 20\n");CHECK(chmod((slow/"bin/reader-experience1-prepare").c_str(),0700)==0);covers::Service cancelled;CHECK(cancelled.request({slow,data/"cancelled",epub.id,epub.sha256}));cancelled.beginQuiesce();until([&]{cancelled.collect();return cancelled.drained();});CHECK(!cancelled.find(epub.id,epub.sha256)&&!cancelled.request({fake,data/"late",epub.id,epub.sha256}));std::puts("COVERS_PASS embedded_cover=metadata pdf=front_page source=unchanged cache=12 cancellation=reaped writes=0");return 0;}catch(const std::exception&e){std::fprintf(stderr,"COVERS_FAIL %s\n",e.what());return 1;}}
